def fatorial(n):
    if n < 0:
        raise ValueError('n deve ser não negativo')
    resultado = 1
    for valor in range(2, n + 1):
        resultado *= valor
    return resultado

def eh_palindromo(texto):
    texto = ''.join(c.lower() for c in texto if c.isalnum())
    return texto == texto[::-1]

