def remover_duplicados(itens):
    vistos = set()
    resultado = []
    for item in itens:
        if item not in vistos:
            vistos.add(item)
            resultado.append(item)
    return resultado

class ContaBancaria:
    def __init__(self, saldo=0):
        if saldo < 0:
            raise ValueError('saldo inicial inválido')
        self.saldo = saldo
    def depositar(self, valor):
        if valor <= 0:
            raise ValueError('valor deve ser positivo')
        self.saldo += valor
        return self.saldo

def media(valores):
    if not valores:
        raise ValueError('lista vazia')
    return sum(valores) / len(valores)

def itens_em_comum(a, b):
    conjunto_b = set(b)
    return [item for item in a if item in conjunto_b]

def converter_inteiros(valores):
    resultado = []
    for valor in valores:
        try:
            resultado.append(int(valor))
        except (ValueError, TypeError):
            continue
    return resultado

def busca_binaria(lista, alvo):
    esquerda, direita = 0, len(lista) - 1
    while esquerda <= direita:
        meio = (esquerda + direita) // 2
        if lista[meio] == alvo:
            return meio
        if lista[meio] < alvo:
            esquerda = meio + 1
        else:
            direita = meio - 1
    return -1

from collections import defaultdict

def agrupar_por_tamanho(palavras):
    grupos = defaultdict(list)
    for palavra in palavras:
        grupos[len(palavra)].append(palavra)
    return dict(grupos)

