def potencia(base, expoente):
    if expoente < 0:
        return 1 / potencia(base, -expoente)
    resultado = 1
    while expoente:
        if expoente % 2:
            resultado *= base
        base *= base
        expoente //= 2
    return resultado

def segundo_maior(numeros):
    distintos = sorted(set(numeros), reverse=True)
    if len(distintos) < 2:
        raise ValueError('são necessários dois valores distintos')
    return distintos[1]

import re
import unicodedata

def criar_slug(texto):
    texto = unicodedata.normalize('NFKD', texto).encode('ascii', 'ignore').decode().lower()
    return re.sub(r'[^a-z0-9]+', '-', texto).strip('-')

def aplicar_desconto(preco, percentual):
    if preco < 0 or not 0 <= percentual <= 100:
        raise ValueError('preço ou percentual inválido')
    return preco * (1 - percentual / 100)
